from hatchet_sdk import Hatchet
from pydantic import BaseModel
import time

hatchet = Hatchet()

class DoubleInput(BaseModel):
    n: int

@hatchet.task()
def double_value(input: DoubleInput):
    return {"result": input.n * 2}

if __name__ == "__main__":
    worker = hatchet.create_worker("my-worker")
    worker.register_workflow(double_value)
    worker.start()

